// 1. Validasi Data Masuk dari TaskFlow
const body = $input.first().json.body || $input.first().json;

if (!body.title || !body.deadline) {
  throw new Error("Data tidak valid: 'title' dan 'deadline' wajib ada!");
}

return {
  task_id: body.task_id || null,
  title: body.title,
  description: body.description || "-",
  deadline: body.deadline,
  priority: (body.priority || 'medium').toUpperCase(),
  status: (body.status || 'pending').toLowerCase()
};

parameters.query:
SELECT id, title, description, deadline, priority, status 
FROM tasks 
WHERE id = {{$json.task_id || 0}} 
LIMIT 1;

