// Hitung selisih waktu ke deadline
const inputData = $input.first().json;

// Ambil data dari query PostgreSQL jika ada, atau gunakan data webhook sebelumnya
const task = (inputData.id) ? inputData : $('Validasi Data').first().json;

const deadlineDate = new Date(task.deadline);
const now = new Date();

const diffMs = deadlineDate.getTime() - now.getTime();
const diffMinutes = Math.floor(diffMs / (1000 * 60));

// Kondisi deadline dekat: belum lewat waktu (diffMinutes >= 0) dan sisa waktu <= 60 menit
const isNear = (diffMinutes >= 0 && diffMinutes <= 60);

return {
  ...task,
  diff_minutes: diffMinutes,
  is_near_deadline: isNear,
  formatted_deadline: deadlineDate.toLocaleString('id-ID', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  })
};

